CREATE TABLE public.billing_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(user_id), provider text NOT NULL DEFAULT 'stripe', environment text NOT NULL CHECK(environment IN ('sandbox','live')), provider_invoice_id text NOT NULL, provider_payment_id text, number text, currency text NOT NULL CHECK(currency ~ '^[a-z]{3}$'), amount_paid_minor bigint NOT NULL DEFAULT 0 CHECK(amount_paid_minor>=0), amount_refunded_minor bigint NOT NULL DEFAULT 0 CHECK(amount_refunded_minor BETWEEN 0 AND amount_paid_minor), status text NOT NULL CHECK(status IN ('draft','open','paid','void','uncollectible')), hosted_invoice_url text, invoice_pdf_url text, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(environment,provider_invoice_id));
GRANT SELECT ON public.billing_invoices TO authenticated; GRANT ALL ON public.billing_invoices TO service_role;
ALTER TABLE public.billing_invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoices_read ON public.billing_invoices FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TRIGGER invoices_updated BEFORE UPDATE ON public.billing_invoices FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX invoices_user ON public.billing_invoices(user_id,created_at DESC);
CREATE TABLE public.refund_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.billing_invoices(id), user_id uuid NOT NULL REFERENCES public.profiles(user_id), reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 10 AND 2000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved_pending_provider','rejected','refunded','failed')), review_note text NOT NULL DEFAULT '', reviewed_by uuid REFERENCES public.profiles(user_id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.refund_requests TO authenticated; GRANT ALL ON public.refund_requests TO service_role;
ALTER TABLE public.refund_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY refunds_read ON public.refund_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_open_refund ON public.refund_requests(invoice_id) WHERE status IN ('pending','approved_pending_provider');
CREATE INDEX refunds_user ON public.refund_requests(user_id,created_at DESC);
CREATE TRIGGER refunds_updated BEFORE UPDATE ON public.refund_requests FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.request_invoice_refund(invoice uuid, explanation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.billing_invoices; request_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT * INTO inv FROM public.billing_invoices WHERE id=invoice AND user_id=auth.uid() FOR UPDATE; IF inv.id IS NULL OR inv.status<>'paid' OR inv.environment<>'live' OR inv.amount_paid_minor<=inv.amount_refunded_minor THEN RAISE EXCEPTION 'Invoice is not eligible'; END IF; INSERT INTO public.refund_requests(invoice_id,user_id,reason) VALUES(inv.id,auth.uid(),btrim(explanation)) RETURNING id INTO request_id; RETURN request_id; END $$;
REVOKE ALL ON FUNCTION public.request_invoice_refund(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_invoice_refund(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.review_invoice_refund(request uuid, decision text, note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF decision NOT IN ('approved_pending_provider','rejected') OR length(btrim(note)) NOT BETWEEN 3 AND 2000 THEN RAISE EXCEPTION 'Invalid review'; END IF; UPDATE public.refund_requests SET status=decision,review_note=btrim(note),reviewed_by=auth.uid(),reviewed_at=now() WHERE id=request AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Request already reviewed or missing'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_invoice_refund(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_invoice_refund(uuid,text,text) TO authenticated;
CREATE TABLE public.billing_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_event_id text NOT NULL, environment text NOT NULL CHECK(environment IN ('sandbox','live')), kind text NOT NULL CHECK(kind IN ('subscription_started','subscription_canceled','payment_received','refund_completed')), user_id uuid REFERENCES public.profiles(user_id), currency text CHECK(currency ~ '^[a-z]{3}$'), amount_minor bigint CHECK(amount_minor>=0), occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(environment,provider_event_id), CHECK((kind IN ('payment_received','refund_completed') AND currency IS NOT NULL AND amount_minor IS NOT NULL) OR kind IN ('subscription_started','subscription_canceled')));
GRANT SELECT ON public.billing_events TO authenticated; GRANT ALL ON public.billing_events TO service_role;
ALTER TABLE public.billing_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_events_admin ON public.billing_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX billing_events_date ON public.billing_events(occurred_at);
CREATE TRIGGER billing_events_updated BEFORE UPDATE ON public.billing_events FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TABLE public.daily_platform_summaries (day date PRIMARY KEY, accounts_total bigint NOT NULL, new_accounts bigint NOT NULL, successful_logins bigint, unique_logins bigint, active_subscriptions bigint, new_subscriptions bigint, canceled_subscriptions bigint, revenue_by_currency jsonb, refunds_by_currency jsonb, payment_source_ready boolean NOT NULL DEFAULT false, login_source_ready boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.daily_platform_summaries TO authenticated; GRANT ALL ON public.daily_platform_summaries TO service_role;
ALTER TABLE public.daily_platform_summaries ENABLE ROW LEVEL SECURITY;
CREATE POLICY summaries_admin ON public.daily_platform_summaries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER summaries_updated BEFORE UPDATE ON public.daily_platform_summaries FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.capture_daily_platform_summary() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d date := (now() AT TIME ZONE 'UTC')::date-1; BEGIN IF d < DATE '2026-10-31' THEN RETURN; END IF; INSERT INTO public.daily_platform_summaries(day,accounts_total,new_accounts) SELECT d,count(*),count(*) FILTER(WHERE created_at>=d::timestamp AT TIME ZONE 'UTC' AND created_at<(d+1)::timestamp AT TIME ZONE 'UTC') FROM public.profiles WHERE user_id IS NOT NULL AND created_at<(d+1)::timestamp AT TIME ZONE 'UTC' ON CONFLICT(day) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.capture_daily_platform_summary() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.capture_daily_platform_summary() TO service_role;
CREATE EXTENSION IF NOT EXISTS pg_cron;
SELECT cron.schedule('museum-daily-summary','17 0 * * *','SELECT public.capture_daily_platform_summary();');
INSERT INTO public.dev_tasks(id,payload) VALUES
('platform-37',jsonb_build_object('id','platform-37','title','Connect Stripe and verified billing events','description','Blocked until owner connects payments and confirms products, prices, countries, tax handling and refund policy. Then implement hosted checkout/customer portal, invoice sync, signature-verified idempotent webhooks, live/test separation, ordering/reconciliation, cancel at period end, payment failure notices, refund partial/full processing with retries and immutable admin audit. Only verified provider events change entitlements or mark refunded; never trust checkout redirects. No card data in the app.','area','Billing','priority','P0','status','blocked','impact',5,'effort',5,'rank',67,'createdAt','2026-10-31')),
('platform-38',jsonb_build_object('id','platform-38','title','Weekly operational report to Carlos','description','Recipient carlosperaltasorolla@gmail.com only. Last completed UTC week, coverage and unavailable metrics explicit. Blocked on an owned verified sender domain and external authenticated scheduler for this external Supabase project. After domain setup scaffold managed email; use event/week idempotency, fixed recipient, protected route, no bulk loop/email queue, monitor suppression and delivery. Weekly preview/export available in admin.','area','Admin','priority','P1','status','blocked','impact',4,'effort',3,'rank',68,'createdAt','2026-10-31')),
('platform-39',jsonb_build_object('id','platform-39','title','Trusted login history and daily billing metrics','description','Daily SQL-only UTC account snapshots enabled from 2026-10-31 at 00:17 UTC. No invented historic totals. Login metrics pending trustworthy server auth audit ingestion; payments pending verified live Stripe events. Add source coverage, retention, UTC boundary and partial refund/currency tests, no session refresh counting, reconcile gaps.','area','Admin','priority','P1','status','blocked','impact',4,'effort',4,'rank',69,'createdAt','2026-10-31'));
UPDATE public.dev_tasks SET payload=payload||jsonb_build_object('status','in_progress','description','Daily account snapshots and admin report table implemented; login and monetary history remain explicitly unavailable until trustworthy auth audit and verified live Stripe event ingestion. See platform-39.') WHERE id='platform-33';